<?php
declare(strict_types=1);

function migrate_wasooli(): void {
 if(one("SELECT value FROM meta WHERE key='wasooli_version'")){migrate_wasooli_discounts();return;}
 transaction(function(){
  run('CREATE TABLE IF NOT EXISTS wasooli_collections(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES accounts(id),operator_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),dated TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),cash_account_id TEXT NOT NULL REFERENCES accounts(id),notes TEXT NOT NULL DEFAULT \'\',operator_entry_id INTEGER UNIQUE REFERENCES operator_cash_entries(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');
  run('CREATE TABLE IF NOT EXISTS wasooli_receipts(collection_id INTEGER NOT NULL REFERENCES wasooli_collections(id),receipt_id INTEGER NOT NULL UNIQUE REFERENCES delivery_cash_receipts(id),PRIMARY KEY(collection_id,receipt_id))');
  run('CREATE INDEX IF NOT EXISTS idx_wasooli_account ON wasooli_collections(account_id,id DESC)');
  run("INSERT OR IGNORE INTO meta(key,value) VALUES('wasooli_version','1')");
 });
 migrate_wasooli_discounts();
}
function migrate_wasooli_discounts(): void {
 if(one("SELECT value FROM meta WHERE key='wasooli_discounts_version'"))return;
 transaction(function(){run('CREATE TABLE IF NOT EXISTS wasooli_discounts(id INTEGER PRIMARY KEY AUTOINCREMENT,collection_id INTEGER NOT NULL REFERENCES wasooli_collections(id),delivery_item_id INTEGER NOT NULL REFERENCES delivery_items(id),amount INTEGER NOT NULL CHECK(amount>0),voucher_id INTEGER REFERENCES vouchers(id),UNIQUE(collection_id,delivery_item_id))');run("INSERT OR IGNORE INTO meta(key,value) VALUES('wasooli_discounts_version','1')");});
}
function wasooli_customer(string $id): array {
 $account=one("SELECT id,name,area,address,mobile,phone,status FROM accounts WHERE id=? AND customer=1",[$id]);if(!$account)throw new InvalidArgumentException('Choose a valid customer.');return $account;
}
// Keep service collections separate from bilty/customer postings. Older combined
// service receipts stay combined where their original split is unavailable.
function wasooli_debts(array $accounts): array {
 $marks=implode(',',array_fill(0,count($accounts),'?'));
 return query("SELECT l.delivery_id,l.delivery_item_id,l.account_id,l.bilty,l.party_to,l.advance,l.bilty_due,l.bilty_received,d.reference,d.dated,MAX(0,l.bilty_due-l.bilty_received) bilty_balance,MAX(0,l.bilty_received-l.bilty_due) bilty_credit,CASE WHEN d.cash_workflow=0 OR COALESCE(c.legacy_services,0)=1 OR l.legacy_service_received<>0 THEN 0 ELSE MAX(0,l.loading-l.loading_received) END loading_balance,CASE WHEN d.cash_workflow=0 OR COALESCE(c.legacy_services,0)=1 OR l.legacy_service_received<>0 THEN 0 ELSE MAX(0,l.suzuki-l.suzuki_received) END suzuki_balance,CASE WHEN d.cash_workflow=0 OR COALESCE(c.legacy_services,0)=1 OR l.legacy_service_received<>0 THEN MAX(0,l.service_due-l.service_received) ELSE 0 END legacy_balance,(SELECT COUNT(*) FROM cash_collection_submissions s WHERE s.delivery_id=d.id AND s.status='pending') pending_cash FROM delivery_unified_lines l JOIN deliveries d ON d.id=l.delivery_id LEFT JOIN delivery_cash_invoices c ON c.delivery_id=d.id WHERE l.account_id IN ($marks) AND NOT(d.delivery_mode='walkin' AND NOT EXISTS(SELECT 1 FROM delivery_cash_receipts vr WHERE vr.delivery_id=d.id) AND EXISTS(SELECT 1 FROM cash_collection_submissions vs WHERE vs.delivery_id=d.id AND vs.status='pending')) ORDER BY l.account_id,d.dated,l.delivery_id,l.delivery_item_id",$accounts);
}
function wasooli_list(array $p): array {
 $search=text($p,'search',120);$area=text($p,'area',100);$where=" WHERE a.customer=1 AND a.status='A'";$args=[];
 if($search!==''){$pattern='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';$where.=" AND (a.name LIKE ? ESCAPE '\\' OR a.id LIKE ? ESCAPE '\\' OR a.area LIKE ? ESCAPE '\\' OR a.mobile LIKE ? ESCAPE '\\' OR a.phone LIKE ? ESCAPE '\\' OR a.mobile2 LIKE ? ESCAPE '\\' OR a.phone2 LIKE ? ESCAPE '\\')";array_push($args,...array_fill(0,7,$pattern));}
 if($area!==''){$where.=' AND a.area=?';$args[]=$area;}
 $sort=match(text($p,'sort',20)){'area'=>"COALESCE(a.area,'') COLLATE NOCASE,a.name COLLATE NOCASE,a.id",'number'=>'a.id',default=>'a.name COLLATE NOCASE,a.id'};
 $customers=query('SELECT a.id,a.name,a.area,a.address,a.mobile,a.phone FROM accounts a'.$where.' ORDER BY '.$sort,$args);$ids=array_column($customers,'id');$byAccount=[];
 // Chunk to stay below SQLite parameter limits for large customer directories.
 foreach(array_chunk($ids,500) as $chunk)foreach(wasooli_debts($chunk) as $line){$sum=(int)$line['bilty_balance']+(int)$line['loading_balance']+(int)$line['suzuki_balance']+(int)$line['legacy_balance'];$id=$line['account_id'];$byAccount[$id]??=['outstanding'=>0,'bilty_balance'=>0,'loading_balance'=>0,'suzuki_balance'=>0,'legacy_balance'=>0,'credit'=>0,'bilties'=>0];$byAccount[$id]['credit']+=(int)$line['bilty_credit'];if($sum<=0)continue;foreach(['bilty_balance','loading_balance','suzuki_balance','legacy_balance'] as $key)$byAccount[$id][$key]+=(int)$line[$key];$byAccount[$id]['outstanding']+=$sum;$byAccount[$id]['bilties']++;}
 $rows=[];foreach($customers as $row)if(($byAccount[$row['id']]['outstanding']??0)>0)$rows[]=$row+$byAccount[$row['id']];$total=count($rows);$page=max(0,min(max(0,(int)ceil($total/30)-1),(int)($p['page']??0)));
 return ['rows'=>array_slice($rows,$page*30,30),'total'=>$total,'page'=>$page,'page_size'=>30,'areas'=>query("SELECT DISTINCT area FROM accounts WHERE customer=1 AND status='A' AND TRIM(COALESCE(area,''))<>'' ORDER BY area COLLATE NOCASE")];
}
function wasooli_details(string $account,array $user,int $page=0): array {
 $customer=wasooli_customer($account);$all=wasooli_debts([$account]);$dues=delivery_customer_dues(['account_ids'=>[$account]]);$summary=$dues['customers'][0];$unpaid=[];$totals=['bilty_balance'=>0,'loading_balance'=>0,'suzuki_balance'=>0,'legacy_balance'=>0];
 foreach($all as $line){$line['balance']=0;foreach(array_keys($totals) as $key){$totals[$key]+=(int)$line[$key];$line['balance']+=(int)$line[$key];}if($line['balance']>0)$unpaid[]=$line;}
 $summary=[...$summary,...$totals,'outstanding'=>array_sum($totals),'bilties'=>count($unpaid)];$count=count($unpaid);$page=max(0,min(max(0,(int)ceil($count/50)-1),$page));$rows=array_slice(array_reverse($unpaid),$page*50,50);
 $history=query("SELECT r.id,r.dated,r.date_known,r.created_by,d.reference,SUM(l.bilty_received+l.service_received) amount,group_concat(CASE WHEN l.bilty_received<>0 OR l.service_received<>0 THEN b.bilty END,', ') bilties FROM delivery_cash_receipt_lines l JOIN delivery_cash_receipts r ON r.id=l.receipt_id JOIN deliveries d ON d.id=r.delivery_id JOIN delivery_cash_lines b ON b.delivery_item_id=l.delivery_item_id WHERE b.account_id=? AND (l.bilty_received<>0 OR l.service_received<>0) GROUP BY r.id ORDER BY r.dated DESC,r.id DESC LIMIT 30",[$account]);
 $legacyHistory=query("SELECT d.reference,d.dated,di.bilty_received+di.service_received amount,COALESCE(CAST(li.BILLTYNO AS TEXT),i.bilty) bilties,li.REC_DATE received_date FROM deliveries d JOIN delivery_items di ON di.delivery_id=d.id JOIN items i ON i.id=di.item_id LEFT JOIN legacy_IND li ON li.INDNO=di.legacy_id WHERE d.cash_workflow=0 AND i.account_id=? AND (di.bilty_received<>0 OR di.service_received<>0) ORDER BY d.dated DESC,di.id DESC LIMIT 30",[$account]);foreach($legacyHistory as $row){$date=substr((string)($row['received_date']??''),0,10);$known=(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date);$history[]=['id'=>0,'dated'=>$known?$date:$row['dated'],'date_known'=>(int)$known,'created_by'=>'Original record','reference'=>$row['reference'],'amount'=>(int)$row['amount'],'bilties'=>$row['bilties']];}usort($history,fn($a,$b)=>strcmp($b['dated'],$a['dated'])?:((int)$b['id']<=>(int)$a['id']));$history=array_slice($history,0,30);
 $last=one('SELECT l.delivery_id FROM delivery_unified_lines l WHERE l.account_id=? ORDER BY l.delivery_id DESC LIMIT 1',[$account]);$operators=[];if($user['role']==='super_admin'){foreach(query("SELECT id,username,full_name FROM users WHERE role='operations' AND active=1 ORDER BY full_name,username") as $operator){$operator['period_token']=operator_cash_token((int)$operator['id']);$operators[]=$operator;}}else $operators[]=['id'=>$user['id'],'username'=>$user['username'],'full_name'=>$user['full_name'],'period_token'=>operator_cash_token((int)$user['id'])];
 $discountHistory=query('SELECT c.dated,w.amount,d.reference,l.bilty,c.actor_id,u.username FROM wasooli_discounts w JOIN wasooli_collections c ON c.id=w.collection_id JOIN delivery_items di ON di.id=w.delivery_item_id JOIN deliveries d ON d.id=di.delivery_id JOIN delivery_unified_lines l ON l.delivery_item_id=di.id JOIN users u ON u.id=c.actor_id WHERE c.account_id=? ORDER BY w.id DESC LIMIT 30',[$account]);
 return ['customer'=>$customer,'summary'=>$summary,'balance_version'=>shipment_version($all),'debts'=>$rows,'debt_total'=>$count,'debt_page'=>$page,'history'=>$history,'discount_history'=>$discountHistory,'has_delivery'=>(bool)$last,'operators'=>$operators,'cash_accounts'=>query("SELECT id,name FROM accounts WHERE status='A' AND (id LIKE '1-101-%' OR id LIKE '1-106-%') ORDER BY id")];
}
function wasooli_save(array $p,array $actor): array {
 $key=text($p,'request_key',100,true);if(!preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$key))throw new InvalidArgumentException('Invalid collection request key.');$hash=shipment_version($p);
 return transaction(function()use($p,$actor,$key,$hash){
  $existing=one('SELECT * FROM wasooli_collections WHERE request_key=?',[$key]);if($existing){if((int)$existing['actor_id']!==(int)$actor['id']||!hash_equals($existing['request_hash'],$hash))throw new RuntimeException('This collection request was already used for different values.',409);return ['id'=>$existing['id'],'amount'=>$existing['amount'],'replayed'=>true];}
  $customer=wasooli_customer(text($p,'account_id',40,true));if($customer['status']!=='A')throw new InvalidArgumentException('Choose an active customer.');$owner=$actor['role']==='super_admin'?$actor:operator_cash_owner($actor,['operator_id'=>(int)($p['operator_id']??0)]);if(!$owner||empty($owner['active'])||!in_array($owner['role'],['operations','super_admin'],true))throw new InvalidArgumentException('Choose an active munshi.');
  if($actor['role']!=='super_admin'&&!hash_equals(operator_cash_token((int)$owner['id']),text($p,'period_token',100,true)))throw new RuntimeException('The munshi ledger was cleared. Refresh before collecting.',409);
  $amount=money($p,'amount');if(!$amount)throw new InvalidArgumentException('Enter an amount greater than zero.');$dated=day($p);if($dated>date('Y-m-d'))throw new InvalidArgumentException('Collection date cannot be in the future.');$cash=text($p,'cash_account_id',40,true);if(!one("SELECT id FROM accounts WHERE id=? AND status='A' AND (id LIKE '1-101-%' OR id LIKE '1-106-%')",[$cash]))throw new InvalidArgumentException('Choose an active cash or bank account.');
  $debts=wasooli_debts([$customer['id']]);if(!hash_equals(shipment_version($debts),text($p,'balance_version',128,true)))throw new RuntimeException('Customer balances changed. Refresh before collecting.',409);
  $discount=money($p,'discount');$discountRemaining=$discount;$discounts=[];
  foreach($debts as $debt){if(!empty($debt['pending_cash']))throw new RuntimeException('A delivery for this customer has cash awaiting approval. Resolve it before collecting.',409);if((int)$debt['advance']>0)continue;$take=min($discountRemaining,(int)$debt['bilty_balance']);if($take){$discounts[]=['delivery_id'=>(int)$debt['delivery_id'],'delivery_item_id'=>(int)$debt['delivery_item_id'],'amount'=>$take];$discountRemaining-=$take;}if(!$discountRemaining)break;}
  if($discountRemaining)throw new InvalidArgumentException('Discount cannot exceed the unpaid bilty balance eligible for discount. Advance bilties and service charges are excluded.');
  foreach($discounts as $part){$deliveryId=$part['delivery_id'];unified_adopt($deliveryId);unified_assess($deliveryId);run('UPDATE delivery_items SET discount=discount+? WHERE id=?',[$part['amount'],$part['delivery_item_id']]);run('UPDATE delivery_cash_lines SET bilty_due=bilty_due-? WHERE delivery_item_id=?',[$part['amount'],$part['delivery_item_id']]);}
  if($discounts)$debts=wasooli_debts([$customer['id']]);
  $outstanding=0;foreach($debts as $debt)foreach(['bilty_balance','loading_balance','suzuki_balance','legacy_balance'] as $field)$outstanding+=(int)$debt[$field];if($amount>$outstanding&&empty($p['confirm_credit']))throw new InvalidArgumentException('Confirm the excess customer credit before saving.');
  $remaining=$amount;$targets=[];foreach($debts as $debt){if(!empty($debt['pending_cash']))throw new RuntimeException('A delivery for this customer has cash awaiting approval. Resolve it before collecting.',409);$deliveryId=(int)$debt['delivery_id'];$lineId=(int)$debt['delivery_item_id'];foreach(['bilty_balance'=>'bilty_received','loading_balance'=>'loading_received','suzuki_balance'=>'suzuki_received','legacy_balance'=>'legacy_service_received'] as $balanceField=>$receiptField){$take=min($remaining,(int)$debt[$balanceField]);if($take){$targets[$deliveryId][$lineId][$receiptField]=($targets[$deliveryId][$lineId][$receiptField]??0)+$take;$remaining-=$take;}if(!$remaining)break;}if(!$remaining)break;}
  if($remaining){if($targets){$deliveryId=array_key_last($targets);$lineId=array_key_last($targets[$deliveryId]);}else{$last=one("SELECT l.delivery_id,l.delivery_item_id FROM delivery_unified_lines l WHERE l.account_id=? AND NOT EXISTS(SELECT 1 FROM cash_collection_submissions s WHERE s.delivery_id=l.delivery_id AND s.status='pending') ORDER BY l.delivery_id DESC,l.delivery_item_id DESC LIMIT 1",[$customer['id']]);if(!$last)throw new InvalidArgumentException('This customer has no eligible delivered bilty to receive a payment against.');$deliveryId=(int)$last['delivery_id'];$lineId=(int)$last['delivery_item_id'];}$targets[$deliveryId][$lineId]['bilty_received']=($targets[$deliveryId][$lineId]['bilty_received']??0)+$remaining;}
  $notes=text($p,'notes',500);run('INSERT INTO wasooli_collections(request_key,request_hash,account_id,operator_id,actor_id,dated,amount,cash_account_id,notes) VALUES(?,?,?,?,?,?,?,?,?)',[$key,$hash,$customer['id'],$owner['id'],$actor['id'],$dated,$amount,$cash,$notes]);$collection=(int)db()->lastInsertId();
  foreach($discounts as $part){$voucher=unified_journal($dated,'Daily Wasooli discount · '.$customer['name'],[unified_entry($customer['id'],-$part['amount']),unified_entry('SYS-BILTY-CLEARING',$part['amount'])]);run('INSERT INTO wasooli_discounts(collection_id,delivery_item_id,amount,voucher_id) VALUES(?,?,?,?)',[$collection,$part['delivery_item_id'],$part['amount'],$voucher]);audit('discount on wasooli','delivery',$part['delivery_id']);}
  foreach($targets as $deliveryId=>$allocation){unified_adopt($deliveryId);$invoice=delivery_cash_invoice($deliveryId);$items=[];foreach($invoice['lines'] as $line){$part=$allocation[(int)$line['delivery_item_id']]??[];$entry=['id'=>$line['delivery_item_id']];foreach(['bilty_received','loading_received','suzuki_received','legacy_service_received'] as $field)$entry[$field]=amount_decimal($part[$field]??0);$items[]=$entry;}$receipt=unified_record_cash(['delivery_id'=>$deliveryId,'version'=>$invoice['version'],'request_key'=>'wasooli-'.hash('sha256',$key.'-'.$deliveryId),'dated'=>$dated,'cash_account_id'=>$cash,'notes'=>mb_substr('Daily Wasooli · '.$customer['name'].($notes?' · '.$notes:''),0,500),'items'=>$items],$actor,true,0,false);run('INSERT INTO wasooli_receipts(collection_id,receipt_id) VALUES(?,?)',[$collection,$receipt['id']]);}
  $entry=null;if($actor['role']!=='super_admin'){$period=operator_cash_open((int)$owner['id'],true);$title='Daily Wasooli · '.$customer['name'];run("INSERT INTO operator_cash_entries(period_id,operator_id,kind,dated,amount,title,notes,cash_account_id,actor_id,actor_name) VALUES(?,?,'collection',?,?,?,?,?,?,?)",[$period['id'],$owner['id'],$dated,$amount,$title,$notes,$cash,$actor['id'],$actor['username']]);$entry=(int)db()->lastInsertId();run('UPDATE wasooli_collections SET operator_entry_id=? WHERE id=?',[$entry,$collection]);}audit('received daily wasooli','wasooli',$collection);
  return ['id'=>$collection,'amount'=>$amount,'discount'=>$discount,'credit'=>$remaining,'operator_entry_id'=>$entry];
 });
}
function wasooli_routes(string $action,string $method,array $p,array $user): void {
 if($action==='wasooli_customers'&&$method==='GET')response(wasooli_list($_GET));
 if($action==='wasooli_customer'&&$method==='GET')response(wasooli_details(text($_GET,'account_id',40,true),$user,max(0,(int)($_GET['page']??0))));
 if($action==='wasooli_collect'&&$method==='POST')response(wasooli_save($p,$user),201);
}
